import{_ as a,H as t,f as l,i}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"13 | 对象回收（上）：如何定位待回收的对象？","description":"","frontmatter":{},"headers":[{"level":2,"title":"什么是 GC？","slug":"什么是-gc","link":"#什么是-gc","children":[]},{"level":2,"title":"GC 的起源","slug":"gc-的起源","link":"#gc-的起源","children":[]},{"level":2,"title":"GC 用来做什么？","slug":"gc-用来做什么","link":"#gc-用来做什么","children":[]},{"level":2,"title":"GC 的主要步骤","slug":"gc-的主要步骤","link":"#gc-的主要步骤","children":[{"level":3,"title":"标记","slug":"标记","link":"#标记","children":[]},{"level":3,"title":"确认可回收对象","slug":"确认可回收对象","link":"#确认可回收对象","children":[]},{"level":3,"title":"GC Root","slug":"gc-root","link":"#gc-root","children":[]},{"level":3,"title":"如何快速定位 GC ROOT？","slug":"如何快速定位-gc-root","link":"#如何快速定位-gc-root","children":[]},{"level":3,"title":"安全点","slug":"安全点","link":"#安全点","children":[]}]},{"level":2,"title":"重点回顾","slug":"重点回顾","link":"#重点回顾","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"点亮你的知识框架图","slug":"点亮你的知识框架图","link":"#点亮你的知识框架图","children":[]}],"relativePath":"云时代的JVM原理与实战/13｜对象回收（上）：如何定位待回收的对象？.md","filePath":"云时代的JVM原理与实战/13｜对象回收（上）：如何定位待回收的对象？.md","lastUpdated":1795541359000}'),o={name:"云时代的JVM原理与实战/13｜对象回收（上）：如何定位待回收的对象？.md"};function r(n,e,p,s,h,c){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="_13-对象回收-上-如何定位待回收的对象" tabindex="-1">13 | 对象回收（上）：如何定位待回收的对象？ <a class="header-anchor" href="#_13-对象回收-上-如何定位待回收的对象" aria-label="Permalink to &quot;13 | 对象回收（上）：如何定位待回收的对象？&quot;">​</a></h1><p>你好，我是康杨。</p><p>在前面几节课中我们主要聊的是对象的创建，也提到了对象的创建与回收相辅相成，相互影响。从今天开始，我们就重点谈一谈对象的回收，也就是 GC。</p><p>所谓垃圾是指对象已经结束了它在运行态下的生命周期，但是依然占据着运行态下堆内存的空间。此时，就需要对该对象所占用的堆内存空间进行回收，以分配给新的待创建的对象。在Java 中，垃圾内存的回收是由 JVM 自动完成的，但是深入掌握 GC，依然是我们写出安全、可靠、高性能的 Java 程序的基础。这也是 Java 程序员必备的技能和面试中的必考点。</p><p>作为 GC 系列的开篇，本节课我们会一起聊聊 GC 的起源、GC 的作用，以及 JVM 是如何快速定位待回收对象的。</p><h2 id="什么是-gc" tabindex="-1">什么是 GC？ <a class="header-anchor" href="#什么是-gc" aria-label="Permalink to &quot;什么是 GC？&quot;">​</a></h2><p>GC 是 Garbage Collection 的缩写，中文叫做垃圾回收。它是一种自动化的内存管理机制，能够识别和回收不再使用的内存空间。在 Java 里，JVM 负责 GC。通过这种方式，Java 程序员无需手动进行内存的分配和回收，从而降低了内存泄漏的风险，提高了开发效率。</p><h2 id="gc-的起源" tabindex="-1">GC 的起源 <a class="header-anchor" href="#gc-的起源" aria-label="Permalink to &quot;GC 的起源&quot;">​</a></h2><p>GC 的概念并非来源于 Java，而是诞生自 1960 年 MIT 的 Lisp 语言，那时候，计算机科学家很有远见地提出了利用自动化技术进行内存管理的可能性。经过几十年的发展，GC 技术在计算机系统的各个领域都得到了广泛地应用。</p><p>JVM 的垃圾回收技术始于 1995 年，SUN 公司（现已被甲骨文公司收购）发布 Java 技术之时。和其他编程语言相比，Java 的一大特点就是它的内存管理采用了垃圾回收技术。也就是从那个时候起，GC 成为了 JVM 生态系统中的重要一环。在 JVM 实现里，虚拟机栈、本地方法栈、程序计数器和线程同生灭，伴随着线程的退出，同步进行着所占用内存的自动清理。所以 , JVM 里的内存垃圾回收主要应用于堆区和方法区所对应的内存空间的管理，在程序的运行态下，这部分内存的分配、使用和回收都是动态的。</p><h2 id="gc-用来做什么" tabindex="-1">GC 用来做什么？ <a class="header-anchor" href="#gc-用来做什么" aria-label="Permalink to &quot;GC 用来做什么？&quot;">​</a></h2><p>GC 的主要目标是借助以下三种方式帮助我们提高程序的运行效率和开发效率。</p><ol><li>减少内存泄漏</li></ol><p>注意，这里说的是减少而不是消除，内存泄漏是生产实践中经常会遇到的比较严重的问题，各种因素都可能会引发内存泄漏，但是 JVM 的自动识别和内存回收机制，能够帮助我们有效地降低内存泄漏的风险。</p><ol start="2"><li>提升内存利用率</li></ol><p>我们都知道内存是非常稀缺的资源，如何提高有限的内存空间的使用率，始终是一个重要的话题。我们前面提到过，为了提升内存使用率，在对象创建阶段 JVM 通过逃逸分析和标量替换，采用对象栈上分配的方式减少堆内存的使用，这些都是提升内存使用率的尝试。GC 通过不断回收不再使用的内存空间，同样实现了提高内存利用率的效果。</p><ol start="3"><li>降低内存管理成本</li></ol><p>GC 被发明之前，开发者是需要自己手动管理内存的分配和释放的，而随着 GC 的诞生，这一部分职责交由底层 JVM 负责，从而有效地减轻了开发者的负担，提升了开发效率。</p><h2 id="gc-的主要步骤" tabindex="-1">GC 的主要步骤 <a class="header-anchor" href="#gc-的主要步骤" aria-label="Permalink to &quot;GC 的主要步骤&quot;">​</a></h2><p>虽然垃圾回收器种类繁多，但垃圾回收的过程基本一致，主要是 4 个阶段：分别是标记（Mark）、清除（Sweep）、整理（Compact）、再分配（Allocation）。</p><h3 id="标记" tabindex="-1">标记 <a class="header-anchor" href="#标记" aria-label="Permalink to &quot;标记&quot;">​</a></h3><p>这个阶段的目标是确定哪些对象是“活动”的，或者说是正在被使用的，哪些对象是“垃圾”，也就是不再被使用了。垃圾回收器会遍历 Java 堆内存里所有的对象，通过引用关系来判断对象是否存活。</p><h3 id="确认可回收对象" tabindex="-1">确认可回收对象 <a class="header-anchor" href="#确认可回收对象" aria-label="Permalink to &quot;确认可回收对象&quot;">​</a></h3><p>确认一个对象是否可以被回收，通常有两种解决方案，分别是引用计数法和可达性算法。</p><ol><li>引用计数法</li></ol><p>这种方法就是在一个对象被引用的时候，计数加 1，引用断开的时候，计数减 1。当一个对象的引用计数为 0 的时候，就说明这个对象可以被清除了。这个算法的问题是，如果一个对象引用另一个对象的同时，另一个对象也引用这个对象，就形成了循环引用。虽然这个时候双方的引用计数都不是 0，但如果仅仅被对方引用实际上却没有存在的价值，就应该被 GC 掉。引用计数法在这种情况下就失效了。</p><ol start="2"><li>可达性算法</li></ol><p>引用计数法的缺陷让我们看到，仅仅从被引用一方去决定一个对象是否应该被回收太片面了。所以我们换一个方向，从一个存活对象引用到的所有对象视角去判断一个对象是否应该被回收。这就是可达性算法。而查找的起点就叫做 GC Root。</p><h3 id="gc-root" tabindex="-1">GC Root <a class="header-anchor" href="#gc-root" aria-label="Permalink to &quot;GC Root&quot;">​</a></h3><p>GC Root（垃圾回收根节点）是垃圾回收器标记存活对象的起点。在执行垃圾回收时，垃圾回收器首先遍历 GC Root，然后从这些起点通过引用关系层层遍历，并将访问到的对象也就是实际应用中正在使用的对象标记为存活。未被访问到的对象则被认为是垃圾，垃圾回收器会回收这些对象所占用的内存空间。在实际应用中，以下类型的对象可作为 GC Root。</p><ul><li><p>类加载器（Class Loaders）：已加载的类会包含引用它的类加载器。由于类加载器负责加载其他 Java 类，因此它是一个关键的 GC Root。</p></li><li><p>方法区中的静态变量（Static Fields）：静态变量存放在方法区中，因为静态变量的生命周期和类相同，会一直存在于整个应用程序运行期间。所以它们可以作为 GC Root 对象。</p></li><li><p>方法区中的常量（Constant Fields）：方法区中的常量本质上与静态变量相似，它们存储在方法区，并且在应用程序运行期间一直存在。因此它们也可以作为 GC Root 对象。</p></li><li><p>虚拟机栈中的本地变量和参数（Local Variables and Method Arguments）：方法调用过程中，在栈帧里分配的本地变量和参数会被引用，这些栈帧会持续存在，直到方法执行完毕或被弹出栈。因此它们也可以被视为 GC Root 对象。</p></li><li><p>本地方法栈中引用的变量：本地方法栈中定义的全局引用变量会引用 Java 对象，通常在本地 C/C++ 代码中定义。这些引用在垃圾回收过程中会被当作 GC Root 对象。</p></li></ul><h3 id="如何快速定位-gc-root" tabindex="-1">如何快速定位 GC ROOT？ <a class="header-anchor" href="#如何快速定位-gc-root" aria-label="Permalink to &quot;如何快速定位 GC ROOT？&quot;">​</a></h3><p>以虚拟机栈为例，保守式垃圾收集会直接线性扫描栈，再判断每一串数字是不是引用，而HotSpot JVM 采用的是准确式垃圾收集方式，所有对象都存放在 OopMap（对象指针映射表）里，当 GC 发生的时候，直接从这个 map 里寻找 GC Root。将 GC Root 存放到 OopMap 有两个触发时间点，分别是类加载完成后和即时编译过程中。</p><p>类加载完成后，HotSpot 就会把对象内什么偏移量上是什么类型的数据计算出来。而即时编译过程中，也会在特定的位置记录下栈里哪些位置是引用。</p><h3 id="安全点" tabindex="-1">安全点 <a class="header-anchor" href="#安全点" aria-label="Permalink to &quot;安全点&quot;">​</a></h3><p>更新 OopMap 需要消耗大量的时间，所以如果每个指令都同步更新一次 OopMap 的动作，显然是非常低效的。所以 HotSpot 虚拟机采用的是批量处理的方式，也就是只在特定位置才进行一次更新记录的操作，把原来的每个指令更新一次转化成 N 个指令更新一次，大大提升了更新的效率和性能，这个更新的时机点也叫做安全点。</p><p>安全点的选择是一个非常重要的考量，如果在程序正在运行的状态进行更新，显然会影响程序的吞吐和性能，那 JVM 以什么标准来选择呢？</p><p>就是让程序长时间执行的指令，这些指令执行的时候，就可以作为安全点。比如当程序正在进行方法调用、循环跳转、异常跳出等操作的时候，才会进行更新 OopMap 的动作，尽量让外界减少对它的感知，整体流程如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/13/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/13/1.png" alt=""></a></p><p>这种感觉就像一位优秀的厨师在做油焖大虾的时候，他会在做这道菜的后期，也就是大虾需要在锅里焖制的那 1、2 分钟的时候，才顺便清理一下台面，而不是在刚开始煸炒大虾的时候同时清理台面，这个选择清理台面的时机对应的正是 JVM 中的安全点。</p><h2 id="重点回顾" tabindex="-1">重点回顾 <a class="header-anchor" href="#重点回顾" aria-label="Permalink to &quot;重点回顾&quot;">​</a></h2><p>好了，这就是今天的主要内容，GC 相关的知识比较繁杂，我总结了 GC 的一些要点来帮助你查漏补缺。</p><p>GC 是一种自动化的内存管理机制，JVM 借助 GC 机制帮我们降低内存管理成本，同时有效提高内存使用率，并减少内存泄漏。随着硬件的快速发展和大并发、低延时的要求，GC 也在朝着管理更大内存、实现更低延时的方向努力。虽然已经出现了 ZGC 和更新的 Shenandoah，但是 JDK 11 以上版本中 G1 还是当前的主流。</p><p>GC 主要包括标记、清除、整理和再分配 4 个阶段。在标记阶段，JVM 是通过 GC root 借用引用分析法来定位待回收对象的。下节课我们会继续讨论后面的三个阶段。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/13/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/13/2.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>最后请你来思考 2 个问题。</p><ol><li><p>JDK11 以后的版本中使用最多的垃圾回收器是什么？</p></li><li><p>JVM 是如何找到待回收对象的？</p></li></ol><p>欢迎你把你思考后的结果分享到评论区，也欢迎你把这节课的知识分享给需要的朋友，我们下节课再见！</p><h2 id="点亮你的知识框架图" tabindex="-1">点亮你的知识框架图 <a class="header-anchor" href="#点亮你的知识框架图" aria-label="Permalink to &quot;点亮你的知识框架图&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/13/3.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/13/3.jpeg" alt=""></a></p>',51)])])}const d=a(o,[["render",r]]);export{g as __pageData,d as default};
